function validate([words, target, startIndex]) {
  if (!Array.isArray(words) || words.length < 1 || words.length > 100) return 'words needs 1 to 100 strings.';
  const ok = (w) => typeof w === 'string' && w.length >= 1 && w.length <= 100 && /^[a-z]+$/.test(w);
  if (!words.every(ok)) return 'Each word has 1 to 100 lowercase letters.';
  if (!ok(target)) return 'target has 1 to 100 lowercase letters.';
  if (!Number.isInteger(startIndex) || startIndex < 0 || startIndex >= words.length) return 'startIndex must be a valid index of words.';
  return null;
}

