function closestTarget(words, target, startIndex) {
  const n = words.length;
  let best = -1;
  for (let i = 0; i < n; i++) {
    if (words[i] !== target) {
      continue;
    }
    const straight = Math.abs(i - startIndex);
    const distance = Math.min(straight, n - straight);
    if (best === -1 || distance < best) {
      best = distance;
    }
  }
  return best;
}

