function closestTarget(words, target, startIndex) {
  const n = words.length;
  for (let steps = 0; steps < n; steps++) {
    if (words[(startIndex + steps) % n] === target) return steps;
    if (words[(startIndex - steps + n * 2) % n] === target) return steps;
  }
  return -1;
}

