function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const n = large ? (rand() < 0.6 ? 100 : int(50, 100)) : int(1, 8);
  const longWords = large && rand() < 0.4;
  const letters = rand() < 0.5 ? 'ab' : 'abcxyz';
  const word = () => {
    const length = longWords ? int(90, 100) : int(1, large ? 4 : 2);
    let text = '';
    for (let k = 0; k < length; k++) text += letters[int(0, letters.length - 1)];
    return text;
  };
  const pool = Array.from({ length: large ? int(3, 30) : int(1, 4) }, word);
  const words = Array.from({ length: n }, () => pool[int(0, pool.length - 1)]);
  const target = rand() < 0.8 ? pool[int(0, pool.length - 1)] : word() + 'q';
  return [words, target, int(0, n - 1)];
}
